"""Seeded, hardware-routed QAOA with exact certification for a small graph bisection."""

from collections.abc import Mapping
from importlib.metadata import PackageNotFoundError, version
from itertools import combinations
import json
import math
import operator
import platform
import time

import networkx as nx
import numpy as np
from scipy.optimize import minimize
from qiskit import QuantumCircuit, transpile
from qiskit.circuit import ParameterVector
from qiskit.transpiler import CouplingMap
from qiskit_aer import AerSimulator


def infer_heavy_hex_ring():
    """Infer only the stated couplers; the resulting graph is the cycle C10."""
    vertices = [f"D{i}" for i in range(5)] + [f"F{i}" for i in range(5)]
    edges = []
    for i in range(5):
        edges.extend([
            (f"D{i}", f"F{i}"),
            (f"F{i}", f"D{(i + 1) % 5}"),
        ])
    return vertices, edges


def _positive_integer(value, name):
    if isinstance(value, (bool, np.bool_)):
        raise ValueError(f"{name} must be a positive integer.")
    try:
        result = operator.index(value)
    except TypeError as exc:
        raise ValueError(f"{name} must be a positive integer.") from exc
    if result < 1:
        raise ValueError(f"{name} must be a positive integer.")
    return int(result)


def _prepare_graph(graph_vertices, graph_edges):
    vertices = list(graph_vertices)
    if not 2 <= len(vertices) <= 20:
        raise ValueError("Exact certification supports between 2 and 20 vertices.")
    if len(set(vertices)) != len(vertices):
        raise ValueError("Vertex labels must be unique.")

    architectural_vertices, architectural_edges = infer_heavy_hex_ring()
    is_specified_chip = set(vertices) == set(architectural_vertices)
    if graph_edges is None:
        if not is_specified_chip:
            raise ValueError("Edges can be inferred only for the specified chip.")
        graph_edges = architectural_edges

    index = {vertex: i for i, vertex in enumerate(vertices)}
    indexed_edges = set()
    for edge in graph_edges:
        endpoints = list(edge)
        if len(endpoints) != 2:
            raise ValueError("Each edge must contain exactly two endpoints.")
        u, v = endpoints
        if u not in index or v not in index:
            raise ValueError(f"Unknown edge endpoint: {(u, v)!r}")
        if u == v:
            raise ValueError("Self-loops are not supported.")
        pair = tuple(sorted((index[u], index[v])))
        if pair in indexed_edges:
            raise ValueError("Duplicate undirected edges are not supported.")
        indexed_edges.add(pair)

    if is_specified_chip:
        expected = {
            tuple(sorted((index[u], index[v])))
            for u, v in architectural_edges
        }
        if indexed_edges != expected:
            raise ValueError(
                "The supplied edges contradict the stated chip architecture."
            )

    indexed_edges = sorted(indexed_edges)
    graph = nx.Graph()
    graph.add_nodes_from(vertices)
    graph.add_edges_from((vertices[i], vertices[j]) for i, j in indexed_edges)
    if not nx.is_connected(graph):
        raise ValueError("This workflow requires a connected coupling graph.")
    return vertices, indexed_edges, graph, is_specified_chip


def _canonical_mask(mask, n):
    """Identify partitions that differ only by exchanging zone labels."""
    return min(mask, ((1 << n) - 1) ^ mask)


def _is_balanced(mask, n):
    return abs(n - 2 * mask.bit_count()) <= n % 2


def _cut_size(mask, indexed_edges):
    return sum(((mask >> i) ^ (mask >> j)) & 1 for i, j in indexed_edges)


def _partition(mask, vertices):
    return [
        [vertex for i, vertex in enumerate(vertices) if not ((mask >> i) & 1)],
        [vertex for i, vertex in enumerate(vertices) if (mask >> i) & 1],
    ]


def _parse_reference(reference, vertices):
    """Accept two communities, a binary vector, or vertex-to-community mapping."""
    if reference is None:
        return None

    n = len(vertices)
    vertex_set = set(vertices)

    if isinstance(reference, Mapping):
        if set(reference) == vertex_set:
            labels = list(dict.fromkeys(reference[vertex] for vertex in vertices))
            if len(labels) != 2:
                raise ValueError("The reference must contain two nonempty zones.")
            groups = [
                [vertex for vertex in vertices if reference[vertex] == label]
                for label in labels
            ]
        elif len(reference) == 2:
            groups = list(reference.values())
        else:
            raise ValueError("Invalid reference-partition mapping.")
    else:
        values = list(reference)
        if len(values) == n and all(
            isinstance(value, (int, np.integer, bool, np.bool_))
            and int(value) in (0, 1)
            for value in values
        ):
            groups = [
                [vertex for vertex, bit in zip(vertices, values) if int(bit) == 0],
                [vertex for vertex, bit in zip(vertices, values) if int(bit) == 1],
            ]
        elif len(values) == 2:
            groups = values
        else:
            raise ValueError(
                "Reference must be two communities or a binary assignment."
            )

    groups = [list(group) for group in groups]
    sets = [set(group) for group in groups]
    if any(len(group) != len(group_set)
           for group, group_set in zip(groups, sets)):
        raise ValueError("A reference zone contains duplicate vertices.")
    if not sets[0] or not sets[1]:
        raise ValueError("Both reference zones must be nonempty.")
    if sets[0] & sets[1] or sets[0] | sets[1] != vertex_set:
        raise ValueError("Reference zones must partition all supplied vertices.")

    mask = sum(1 << i for i, vertex in enumerate(vertices) if vertex in sets[1])
    return _canonical_mask(mask, n)


def _exact_balanced_optimum(n, indexed_edges):
    """Exhaust all balanced bipartitions, counting complements only once."""
    k = n // 2
    if n % 2 == 0:
        subsets = (
            (0,) + remainder
            for remainder in combinations(range(1, n), k - 1)
        )
    else:
        subsets = combinations(range(n), k)

    optimal_cut = math.inf
    optimal_masks = set()
    examined = 0
    for subset in subsets:
        mask = _canonical_mask(sum(1 << i for i in subset), n)
        cut = _cut_size(mask, indexed_edges)
        examined += 1
        if cut < optimal_cut:
            optimal_cut = cut
            optimal_masks = {mask}
        elif cut == optimal_cut:
            optimal_masks.add(mask)

    return int(optimal_cut), optimal_masks, examined


def _partition_metrics(mask, vertices, indexed_edges, graph, optimal_cut):
    zones = _partition(mask, vertices)
    cut = _cut_size(mask, indexed_edges)
    volumes = [sum(graph.degree(vertex) for vertex in zone) for zone in zones]
    n = len(vertices)
    return {
        "modularity_score": float(
            nx.algorithms.community.quality.modularity(
                graph, [set(zone) for zone in zones], weight=None
            )
        ),
        "normalized_cut_score": float(cut / volumes[0] + cut / volumes[1]),
        "balance_constraint_score": float(
            1.0 - abs(len(zones[0]) - len(zones[1])) / n
        ),
        "approximation_ratio": float(cut / optimal_cut),
        "cut_size": int(cut),
        "zone_sizes": [len(zone) for zone in zones],
        "satisfies_balance_constraint": bool(_is_balanced(mask, n)),
    }


def _build_routed_qaoa(
    n, indexed_edges, p_layers, lambda_balance, lambda_cut, simulator, seed
):
    """
    Minimize H = lambda_cut * cut(x)
               + lambda_balance * (sum_i x_i - n/2)^2.

    With x_i=(1-Z_i)/2, the ZZ coefficient is lambda_balance/2
    for every pair, minus lambda_cut/2 on graph edges. Constants
    do not affect the QAOA state. RZZ(theta)=exp(-i theta ZZ/2).

    Dense balance-penalty interactions are logical interactions, not
    additional chip couplers. Transpilation routes every CX through
    the supplied physical coupling graph.
    """
    gammas = ParameterVector("gamma", p_layers)
    betas = ParameterVector("beta", p_layers)
    edge_set = set(indexed_edges)

    circuit = QuantumCircuit(n, n)
    circuit.h(range(n))
    for layer in range(p_layers):
        for i, j in combinations(range(n), 2):
            coefficient = lambda_balance / 2.0
            if (i, j) in edge_set:
                coefficient -= lambda_cut / 2.0
            if coefficient != 0.0:
                circuit.rzz(2.0 * coefficient * gammas[layer], i, j)
        for i in range(n):
            circuit.rx(2.0 * betas[layer], i)
    circuit.measure(range(n), range(n))

    directed_edges = [
        directed
        for i, j in indexed_edges
        for directed in ((i, j), (j, i))
    ]
    compiled = transpile(
        circuit,
        backend=simulator,
        basis_gates=["rz", "sx", "x", "cx"],
        coupling_map=CouplingMap(directed_edges),
        initial_layout=list(range(n)),
        layout_method="trivial",
        routing_method="sabre",
        optimization_level=1,
        seed_transpiler=seed,
    )

    # Measurement remapping preserves logical qubit i -> classical bit i.
    allowed = set(directed_edges)
    for instruction in compiled.data:
        if instruction.operation.name == "cx":
            pair = tuple(compiled.find_bit(q).index for q in instruction.qubits)
            if pair not in allowed:
                raise RuntimeError("Transpilation produced a forbidden coupler.")

    return compiled, list(gammas) + list(betas)


def _sample_counts(simulator, circuit, parameters, angles, shots, seed):
    bound = circuit.assign_parameters(
        {parameter: float(value) for parameter, value in zip(parameters, angles)},
        inplace=False,
        strict=False,
    )
    counts = simulator.run(
        bound, shots=shots, seed_simulator=int(seed)
    ).result().get_counts()

    # Qiskit displays c[n-1]...c[0]; integer bit i therefore labels vertex i.
    return {
        int(bitstring.replace(" ", ""), 2): int(count)
        for bitstring, count in counts.items()
    }


def _package_versions():
    versions = {"python": platform.python_version()}
    for package in ("qiskit", "qiskit-aer", "numpy", "scipy", "networkx"):
        try:
            versions[package] = version(package)
        except PackageNotFoundError:
            versions[package] = None
    return versions


def solve_graph_partition_qaoa(
    graph_vertices,
    graph_edges,
    known_reference_partition,
    p_layers=2,
    lambda_balance=1.0,
    lambda_cut=3.0,
    opt_shots=1024,
    final_shots=4096,
    maxiter=80,
    n_repro_runs=3,
    seed=42,
):
    """
    Return an optimal balanced two-zone partition using QAOA plus exact checking.

    Hard feasibility requires equal zone sizes for even n, hence 5/5 here.
    The soft QAOA balance penalty guides sampling but does not itself enforce
    feasibility. Only balanced samples qualify; exhaustive enumeration both
    certifies optimality and supplies a disclosed fallback when needed.

    Metric conventions:
      modularity_score: standard unweighted Newman-Girvan modularity.
      normalized_cut_score: cut/volume(A) + cut/volume(B); lower is better.
      balance_constraint_score: 1 - |size(A)-size(B)|/n; 1 means equal sizes.
      approximation_ratio: returned_cut / exact_balanced_optimal_cut.
        This is a minimization ratio: >=1, with 1 optimal.
      runtime: total measured wall-clock seconds, excluding module imports.
      reproducibility: seed policy, versions, and independent seeded trials.

    known_reference_partition is validated and reported, but is not assumed
    optimal and never substitutes for the exact approximation-ratio denominator.

    Architectural edges are unweighted proxies for possible cross-zone gates.
    Actual CNOT counts cannot be inferred without a circuit or traffic model.
    On the specified ring, an optimal balanced cut has 2 crossing edges,
    modularity 0.3, normalized cut 0.4, balance score 1, and ratio 1.
    """
    started = time.perf_counter()
    p_layers = _positive_integer(p_layers, "p_layers")
    opt_shots = _positive_integer(opt_shots, "opt_shots")
    final_shots = _positive_integer(final_shots, "final_shots")
    maxiter = _positive_integer(maxiter, "maxiter")
    n_repro_runs = _positive_integer(n_repro_runs, "n_repro_runs")

    if isinstance(seed, (bool, np.bool_)):
        raise ValueError("seed must be an integer in [0, 2**32).")
    try:
        seed = int(operator.index(seed))
    except TypeError as exc:
        raise ValueError("seed must be an integer in [0, 2**32).") from exc
    if not 0 <= seed < 2**32:
        raise ValueError("seed must be an integer in [0, 2**32).")

    lambda_balance = float(lambda_balance)
    lambda_cut = float(lambda_cut)
    if not math.isfinite(lambda_balance) or lambda_balance < 0:
        raise ValueError("lambda_balance must be finite and nonnegative.")
    if not math.isfinite(lambda_cut) or lambda_cut <= 0:
        raise ValueError("lambda_cut must be finite and positive.")

    vertices, indexed_edges, graph, is_specified_chip = _prepare_graph(
        graph_vertices, graph_edges
    )
    n = len(vertices)
    reference_mask = _parse_reference(known_reference_partition, vertices)

    exact_started = time.perf_counter()
    optimal_cut, optimal_masks, examined = _exact_balanced_optimum(
        n, indexed_edges
    )
    exact_seconds = time.perf_counter() - exact_started
    canonical_exact_mask = min(optimal_masks)

    compile_started = time.perf_counter()
    simulator = AerSimulator(
        method="statevector",
        max_parallel_threads=1,
        max_parallel_experiments=1,
        max_parallel_shots=1,
    )
    compiled, parameters = _build_routed_qaoa(
        n, indexed_edges, p_layers, lambda_balance, lambda_cut, simulator, seed
    )
    compile_seconds = time.perf_counter() - compile_started

    energy_cache = {}

    def energy(mask):
        if mask not in energy_cache:
            energy_cache[mask] = (
                lambda_cut * _cut_size(mask, indexed_edges)
                + lambda_balance * (mask.bit_count() - n / 2.0) ** 2
            )
        return energy_cache[mask]

    run_reports = []
    returned_masks = []
    sampled_optimal_masks = set()
    qaoa_started = time.perf_counter()

    for run_index in range(n_repro_runs):
        run_started = time.perf_counter()
        run_seed = (seed + run_index) % (2**32)
        objective_seed = (run_seed + 1_000_003) % (2**32)
        final_seed = (run_seed + 2_000_003) % (2**32)
        rng = np.random.default_rng(run_seed)
        initial_angles = np.concatenate([
            rng.uniform(0.0, np.pi, p_layers),
            rng.uniform(0.0, np.pi / 2.0, p_layers),
        ])

        best = {"energy": math.inf, "angles": initial_angles.copy()}
        evaluations = 0

        def objective(angles):
            nonlocal evaluations
            counts = _sample_counts(
                simulator, compiled, parameters, angles,
                opt_shots, objective_seed
            )
            estimate = sum(
                count * energy(mask) for mask, count in counts.items()
            ) / sum(counts.values())
            evaluations += 1
            if estimate < best["energy"]:
                best["energy"] = float(estimate)
                best["angles"] = np.asarray(angles, dtype=float).copy()
            return float(estimate)

        # A fixed objective seed gives reproducible common random numbers.
        # Final sampling uses a different seed to assess the selected angles.
        optimization = minimize(
            objective,
            initial_angles,
            method="COBYLA",
            options={"maxiter": maxiter, "rhobeg": 0.5, "tol": 1e-3},
        )
        final_counts = _sample_counts(
            simulator, compiled, parameters, best["angles"],
            final_shots, final_seed
        )
        observed_shots = sum(final_counts.values())
        feasible_counts = {
            mask: count for mask, count in final_counts.items()
            if _is_balanced(mask, n)
        }
        sampled_mask = None
        if feasible_counts:
            sampled_mask = min(
                {_canonical_mask(mask, n) for mask in feasible_counts},
                key=lambda mask: (_cut_size(mask, indexed_edges), mask),
            )

        qaoa_found_optimum = sampled_mask in optimal_masks
        if qaoa_found_optimum:
            returned_mask = sampled_mask
            sampled_optimal_masks.add(sampled_mask)
        else:
            returned_mask = canonical_exact_mask

        returned_masks.append(returned_mask)
        metrics = _partition_metrics(
            returned_mask, vertices, indexed_edges, graph, optimal_cut
        )
        sampled_cut = (
            _cut_size(sampled_mask, indexed_edges)
            if sampled_mask is not None else None
        )
        optimal_sample_count = sum(
            count for mask, count in feasible_counts.items()
            if _canonical_mask(mask, n) in optimal_masks
        )

        run_reports.append({
            "run_index": run_index,
            "seed": run_seed,
            "objective_simulator_seed": objective_seed,
            "final_simulator_seed": final_seed,
            "objective_evaluations": evaluations,
            "optimizer_success": bool(optimization.success),
            "optimizer_message": str(optimization.message),
            "best_sampled_objective_energy": float(best["energy"]),
            "optimized_gammas": best["angles"][:p_layers].tolist(),
            "optimized_betas": best["angles"][p_layers:].tolist(),
            "final_sampled_objective_energy": float(sum(
                count * energy(mask) for mask, count in final_counts.items()
            ) / observed_shots),
            "feasible_sample_fraction": float(
                sum(feasible_counts.values()) / observed_shots
            ),
            "optimal_sample_fraction": float(
                optimal_sample_count / observed_shots
            ),
            "qaoa_best_partition": (
                _partition(sampled_mask, vertices)
                if sampled_mask is not None else None
            ),
            "qaoa_best_cut_size": sampled_cut,
            "qaoa_approximation_ratio": (
                float(sampled_cut / optimal_cut)
                if sampled_cut is not None else None
            ),
            "qaoa_found_optimum": bool(qaoa_found_optimum),
            "used_exact_fallback": not qaoa_found_optimum,
            "returned_partition": _partition(returned_mask, vertices),
            "returned_metrics": metrics,
            "runtime_seconds": float(time.perf_counter() - run_started),
        })

    qaoa_seconds = time.perf_counter() - qaoa_started

    # Prefer an actually sampled optimum; otherwise use the exact fallback.
    selected_mask = (
        min(sampled_optimal_masks)
        if sampled_optimal_masks else canonical_exact_mask
    )
    metrics = _partition_metrics(
        selected_mask, vertices, indexed_edges, graph, optimal_cut
    )
    crossing_edges = [
        [vertices[i], vertices[j]]
        for i, j in indexed_edges
        if ((selected_mask >> i) ^ (selected_mask >> j)) & 1
    ]

    reference_report = None
    if reference_mask is not None:
        reference_report = {
            "partition": _partition(reference_mask, vertices),
            "metrics": _partition_metrics(
                reference_mask, vertices, indexed_edges, graph, optimal_cut
            ),
            "is_balanced_optimum": bool(reference_mask in optimal_masks),
        }

    modularities = [
        report["returned_metrics"]["modularity_score"] for report in run_reports
    ]
    returned_cuts = [
        report["returned_metrics"]["cut_size"] for report in run_reports
    ]

    result = {
        **metrics,
        "partition": _partition(selected_mask, vertices),
        "cross_zone_edges": crossing_edges,
        "solution_source": (
            "qaoa_samples_with_exact_certificate"
            if sampled_optimal_masks else "exact_fallback"
        ),
        "graph": {
            "vertices": vertices,
            "edges": [[vertices[i], vertices[j]] for i, j in indexed_edges],
            "topology": "C10 alternating data/flag ring" if is_specified_chip
                        else "supplied connected undirected graph",
            "edge_weights": "unit architectural coupler weights",
        },
        "exact_certificate": {
            "method": "exhaustive balanced bipartitions modulo zone exchange",
            "bipartitions_examined": examined,
            "optimal_cut_size": optimal_cut,
            "number_of_optimal_bipartitions": len(optimal_masks),
            "certified_optimal": True,
            "optimality_is_from_exact_enumeration_not_qaoa": True,
        },
        "known_reference": reference_report,
        "configuration": {
            "p_layers": p_layers,
            "lambda_balance": lambda_balance,
            "lambda_cut": lambda_cut,
            "opt_shots": opt_shots,
            "final_shots": final_shots,
            "maxiter": maxiter,
            "hard_balance": "zone sizes differ by at most n modulo 2",
            "backend": "qiskit_aer.AerSimulator(method='statevector')",
            "noise_model": None,
            "physical_routing": "bidirectional stated coupling edges only",
            "compiled_depth": int(compiled.depth()),
            "compiled_gate_counts": {
                str(gate): int(count)
                for gate, count in compiled.count_ops().items()
            },
        },
        "reproducibility": {
            "base_seed": seed,
            "n_runs": n_repro_runs,
            "run_seeds": [report["seed"] for report in run_reports],
            "seed_policy": "(base_seed + run_index) modulo 2**32",
            "transpiler_seed": seed,
            "fixed_objective_seed_per_run": True,
            "simulator_threads": 1,
            "same_seed_repeat_verified": False,
            "scope": (
                "Fixed seeds and single-thread simulation support repeatability "
                "on the same software/platform; runtimes are not reproducible. "
                "Different optimal partitions can have identical objective scores."
            ),
            "versions": _package_versions(),
            "certified_optimal_run_fraction": float(np.mean([
                cut == optimal_cut for cut in returned_cuts
            ])),
            "qaoa_optimal_run_fraction": float(np.mean([
                report["qaoa_found_optimum"] for report in run_reports
            ])),
            "mean_optimal_sample_fraction": float(np.mean([
                report["optimal_sample_fraction"] for report in run_reports
            ])),
            "returned_cut_std": float(np.std(returned_cuts)),
            "returned_modularity_mean": float(np.mean(modularities)),
            "returned_modularity_std": float(np.std(modularities)),
            "partition_agreement_with_first_run": float(np.mean([
                mask == returned_masks[0] for mask in returned_masks
            ])),
            "runs": run_reports,
        },
        "runtime_breakdown": {
            "exact_certification_seconds": float(exact_seconds),
            "circuit_construction_and_routing_seconds": float(compile_seconds),
            "qaoa_runs_seconds": float(qaoa_seconds),
        },
    }
    result["runtime"] = float(time.perf_counter() - started)
    return result


def main():
    vertices, edges = infer_heavy_hex_ring()
    reference = [
        ["D0", "F0", "D1", "F1", "D2"],
        ["F2", "D3", "F3", "D4", "F4"],
    ]
    result = solve_graph_partition_qaoa(
        vertices,
        edges,
        known_reference_partition=reference,
        p_layers=2,
        lambda_balance=1.0,
        lambda_cut=3.0,
        opt_shots=1024,
        final_shots=4096,
        maxiter=80,
        n_repro_runs=3,
        seed=42,
    )
    print(json.dumps(result, indent=2, allow_nan=False))


if __name__ == "__main__":
    main()

