def infer_heavy_hex_ring():
    """Infer only the stated couplers; the resulting graph is the cycle C10."""
    vertices = [f"D{i}" for i in range(5)] + [f"F{i}" for i in range(5)]
    edges = []
    for i in range(5):
        edges.extend([
            (f"D{i}", f"F{i}"),
            (f"F{i}", f"D{(i + 1) % 5}"),
